if (!function_exists('treasuryReceiptNextAction')) {
    function treasuryReceiptNextAction(array $receipt): array {
        $url=APP_URL.'/treasury/encaissement-voir/'.(int)$receipt['id'];
        $actions=[
            'brouillon'=>['label'=>'Validation requise','owner'=>'Contrôle comptable','button'=>'Examiner','icon'=>'bi-shield-check','tone'=>'warning','url'=>$url],
            'valide'=>['label'=>'Recette comptabilisée','owner'=>$receipt['validated_by_nom']?:'Cycle terminé','button'=>'Consulter','icon'=>'bi-check2-circle','tone'=>'success','url'=>$url],
            'annule'=>['label'=>'Encaissement annulé','owner'=>'Cycle clôturé','button'=>'Consulter','icon'=>'bi-slash-circle','tone'=>'secondary','url'=>$url],
        ];
        return $actions[$receipt['status']]??['label'=>'Suivi requis','owner'=>'Trésorerie','button'=>'Consulter','icon'=>'bi-arrow-right-circle','tone'=>'secondary','url'=>$url];
    }
}
if (!function_exists('treasuryReceiptWaitingDays')) {
    function treasuryReceiptWaitingDays(array $receipt): int {
        $anchor=$receipt['status']==='valide'?($receipt['validated_at']??$receipt['created_at']):($receipt['cancelled_at']??$receipt['created_at']);
        $timestamp=strtotime((string)$anchor);
        return $timestamp?max(0,(int)floor((time()-$timestamp)/86400)):0;
    }
}
