<script>
var receiptKpiData=<?= json_encode($receiptKpiDetails,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;
function escapeReceiptHtml(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;')}
function openReceiptKpi(metric){var data=receiptKpiData[metric];if(!data)return;document.getElementById('receiptKpiDetailModalLabel').textContent=data.title;document.getElementById('receiptKpiDetailSubtitle').textContent=data.subtitle;document.getElementById('receiptKpiCount').textContent=Number(data.count||0).toLocaleString('fr-FR');document.getElementById('receiptKpiTotal').textContent=Number(data.total_usd||0).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' USD';document.getElementById('receiptKpiAverage').textContent=Number(data.average_usd||0).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' USD';var body=document.getElementById('receiptKpiDetailBody');if(!data.rows.length){body.innerHTML='<tr><td colspan="9" class="text-center text-muted py-5"><i class="bi bi-inboxes fs-3 d-block mb-2"></i>Aucun encaissement dans cet indicateur.</td></tr>'}else{body.innerHTML=data.rows.map(function(row){var cls=row.status==='Validé'?'success':(row.status==='Brouillon'?'warning text-dark':'secondary');return '<tr><td><strong class="text-primary">'+escapeReceiptHtml(row.number)+'</strong></td><td class="text-nowrap">'+escapeReceiptHtml(row.date)+'</td><td>'+escapeReceiptHtml(row.payer)+'</td><td style="max-width:250px">'+escapeReceiptHtml(row.object)+'</td><td><strong>'+escapeReceiptHtml(row.account)+'</strong><div class="text-muted small">'+escapeReceiptHtml(row.method)+'</div></td><td class="text-end fw-semibold text-nowrap">'+Number(row.amount_usd||0).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' USD</td><td><span class="badge bg-'+cls+'">'+escapeReceiptHtml(row.status)+'</span></td><td class="text-nowrap">'+escapeReceiptHtml(row.action)+'</td><td><a class="btn btn-outline-primary btn-sm" href="'+escapeReceiptHtml(row.url)+'"><i class="bi bi-eye"></i></a></td></tr>'}).join('')}bootstrap.Modal.getOrCreateInstance(document.getElementById('receiptKpiDetailModal')).show()}
document.querySelectorAll('.receipt-kpi-card').forEach(function(card){card.addEventListener('click',function(){openReceiptKpi(card.dataset.kpi)});card.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();openReceiptKpi(card.dataset.kpi)}})});
$(function(){var el=$('#tableEncaissements');if(!el.length||!$.fn.DataTable)return;var table=el.DataTable({pageLength:25,lengthMenu:[[10,25,50,100,-1],[10,25,50,100,'Toutes']],order:[[1,'desc'],[0,'desc']],stateSave:true,autoWidth:false,columnDefs:[{orderable:false,targets:5},{className:'text-nowrap',targets:[0,1,4]}],language:{url:'//cdn.datatables.net/plug-ins/1.13.4/i18n/fr-FR.json',search:'Rechercher dans le tableau :',lengthMenu:'Afficher _MENU_ lignes'}});$('#receiptQuickViews .receipt-view-btn').on('click',function(){$('#receiptQuickViews .receipt-view-btn').removeClass('active');$(this).addClass('active');table.column(5).search($(this).data('status')||'').draw()})});
</script>
